ProcessBuilder pb = new ProcessBuilder(javaExe, "-Xms32m", "-Xmx32m", "-cp", classes, "HeapPrinterDemo");
pb.redirectErrorStream(true);
Process p = pb.start();
String out = new String(p.getInputStream().readAllBytes());
if (!p.waitFor(10, java.util.concurrent.TimeUnit.SECONDS)) p.destroyForcibly();
System.out.println(out);

Path log=Files.createTempFile("gc-", ".log");
ProcessBuilder pb=new ProcessBuilder(javaExe,"-Xlog:gc:file="+log,"-cp",classes,"Demo");
Process p=pb.start(); p.waitFor(10,TimeUnit.SECONDS);
System.out.println(Files.readString(log));
